import { app, BrowserWindow, ipcMain, Menu, nativeTheme, session, shell, type IpcMainInvokeEvent } from 'electron'
import { writeFile } from 'node:fs/promises'
import { join } from 'node:path'
import { IPC } from '@shared/api'
import { APP_ORIGIN, CONTENT_SECURITY_POLICY, handleAppScheme, registerAppScheme } from './appProtocol'
import { exportProgress, importProgress, loadProgress, saveProgress } from './progressStore'
import { loadWindowState, trackWindowState } from './windowState'
// Bundled next to the main process by electron-vite (generated by `npm run icons`).
import iconPath from '../../build/icon.ico?asset'

const devServerUrl = !app.isPackaged ? process.env['ELECTRON_RENDERER_URL'] : undefined

registerAppScheme()

// Groups the window under "Datara" with its own icon in the Windows taskbar (matches appId in electron-builder.yml),
// including when started from the desktop shortcut through npm's Electron.
app.setAppUserModelId('local.datara.app')

// Only one copy of the app at a time, so two windows never fight over the progress file.
if (!app.requestSingleInstanceLock()) {
  app.quit()
} else {
  app.on('second-instance', () => {
    const win = BrowserWindow.getAllWindows()[0]
    if (win) {
      if (win.isMinimized()) win.restore()
      win.focus()
    }
  })
  app.whenReady().then(start)
}

/** True for URLs that belong to the app itself. */
function isAppUrl(url: string): boolean {
  return url.startsWith(`${APP_ORIGIN}/`) || (!!devServerUrl && url.startsWith(devServerUrl))
}

function assertTrustedSender(event: IpcMainInvokeEvent): void {
  const url = event.senderFrame?.url ?? ''
  if (!isAppUrl(url)) throw new Error('Blocked IPC call from untrusted page')
}

function hardenSecurity(): void {
  // The app never needs camera, microphone, notifications, etc.
  session.defaultSession.setPermissionRequestHandler((_wc, _permission, callback) => callback(false))
  session.defaultSession.setPermissionCheckHandler(() => false)

  // In development the page comes from Vite's local server, so the security
  // policy is added here. Vite needs inline scripts and a websocket for hot reload.
  if (devServerUrl) {
    const devPolicy = CONTENT_SECURITY_POLICY.replace(
      "script-src 'self'",
      "script-src 'self' 'unsafe-inline'"
    ).replace("connect-src 'self'", "connect-src 'self' ws://localhost:*")
    session.defaultSession.webRequest.onHeadersReceived((details, callback) => {
      callback({
        responseHeaders: { ...details.responseHeaders, 'Content-Security-Policy': [devPolicy] }
      })
    })
  }

  app.on('web-contents-created', (_event, contents) => {
    // Never navigate the app window away from the app.
    contents.on('will-navigate', (event) => {
      if (!isAppUrl(event.url)) event.preventDefault()
    })
    // Links to websites (e.g. lesson citations) open in the normal web browser.
    contents.setWindowOpenHandler(({ url }) => {
      if (url.startsWith('https://')) void shell.openExternal(url)
      return { action: 'deny' }
    })
    contents.on('will-attach-webview', (event) => event.preventDefault())
  })
}

function registerIpc(): void {
  ipcMain.handle(IPC.progressLoad, (event) => {
    assertTrustedSender(event)
    return loadProgress()
  })
  ipcMain.handle(IPC.progressSave, (event, data: unknown) => {
    assertTrustedSender(event)
    return saveProgress(data)
  })
  ipcMain.handle(IPC.progressExport, (event, data: unknown) => {
    assertTrustedSender(event)
    return exportProgress(BrowserWindow.fromWebContents(event.sender), data)
  })
  ipcMain.handle(IPC.progressImport, (event) => {
    assertTrustedSender(event)
    return importProgress(BrowserWindow.fromWebContents(event.sender))
  })
  ipcMain.handle(IPC.windowIsFullScreen, (event) => {
    assertTrustedSender(event)
    return BrowserWindow.fromWebContents(event.sender)?.isFullScreen() ?? false
  })
  ipcMain.handle(IPC.windowToggleFullScreen, (event) => {
    assertTrustedSender(event)
    const win = BrowserWindow.fromWebContents(event.sender)
    if (!win) return false
    win.setFullScreen(!win.isFullScreen())
    return win.isFullScreen()
  })
}

function createWindow(): BrowserWindow {
  const state = loadWindowState()
  const win = new BrowserWindow({
    width: state.bounds?.width ?? 1280,
    height: state.bounds?.height ?? 820,
    ...(state.bounds ? { x: state.bounds.x, y: state.bounds.y } : {}),
    minWidth: 960,
    minHeight: 620,
    show: false,
    title: 'Datara',
    icon: iconPath,
    // Matches the page background, so the window doesn't flash the wrong colour before the page loads.
    backgroundColor: nativeTheme.shouldUseDarkColors ? '#0b1120' : '#f8fafc',
    autoHideMenuBar: true,
    webPreferences: {
      preload: join(__dirname, '../preload/index.js'),
      contextIsolation: true,
      nodeIntegration: false,
      sandbox: true,
      webSecurity: true,
      spellcheck: false
    }
  })

  win.once('ready-to-show', () => {
    if (process.env['DATARA_SELFTEST']) return
    if (state.maximized) win.maximize()
    win.show()
    if (state.fullScreen) win.setFullScreen(true)
  })
  trackWindowState(win, state)

  // F11 toggles full screen. Handled here (not by a menu) because the installed app has no menu.
  // preventDefault also stops Electron's default menu shortcut from toggling it a second time.
  win.webContents.on('before-input-event', (event, input) => {
    if (input.type === 'keyDown' && input.key === 'F11' && !input.control && !input.alt && !input.meta) {
      event.preventDefault()
      win.setFullScreen(!win.isFullScreen())
    }
  })
  // Keep the interface's full-screen button in sync, however full screen was changed.
  win.on('enter-full-screen', () => win.webContents.send(IPC.windowFullScreenChanged, true))
  win.on('leave-full-screen', () => win.webContents.send(IPC.windowFullScreenChanged, false))

  if (devServerUrl) void win.loadURL(devServerUrl)
  else void win.loadURL(`${APP_ORIGIN}/index.html`)

  return win
}

/**
 * Automated check used by `npm run selftest`: loads the app hidden, runs the
 * SQL and Python engines inside the real window, writes the results to a file
 * and quits. Proves the packaged app works offline.
 */
function runSelfTest(win: BrowserWindow, outFile: string): void {
  win.webContents.once('did-finish-load', async () => {
    let result: unknown
    try {
      result = await win.webContents.executeJavaScript('window.__dataraSelfTest()', true)
    } catch (err) {
      result = { ok: false, error: String(err) }
    }
    await writeFile(outFile, JSON.stringify(result, null, 2), 'utf8')
    app.exit((result as { ok?: boolean })?.ok ? 0 : 1)
  })
}

function start(): void {
  if (app.isPackaged) Menu.setApplicationMenu(null)
  if (!devServerUrl) handleAppScheme(join(__dirname, '../renderer'))
  hardenSecurity()
  registerIpc()

  const win = createWindow()
  const selfTestOut = process.env['DATARA_SELFTEST_OUT']
  if (process.env['DATARA_SELFTEST'] && selfTestOut) runSelfTest(win, selfTestOut)

  app.on('window-all-closed', () => app.quit())
}
